Translate("ptBR", "twilight-lord-kelris", {
	title = "Senhor do Crepúsculo Kelris",
	subtitle = "Senhor do Martelo do Crepúsculo nas Profundezas",
	found = [=[O Sacrário do Santuário Lunar, diante do altar dos Deuses Antigos]=],
