			title = "Resumo",
			text = [=[O Senhor do Crepúsculo Kelris lidera o {link:twilight-s-hammer}Martelo do Crepúsculo{/link} nas {link:blackfathom-deeps}Profundezas Negras{/link}. Ele permanece em transe no sacrário do velho templo, ao lado do altar onde o culto faz suas oferendas. Sob seu comando, os cultistas sacrificam inocentes à hidra {link:aku-mai}Aku'mai{/link} e, em troca, ganham poder. Kelris maneja a magia da sombra e do sono, e em batalha pode lançar seus inimigos num sono indefeso.]=],
		},
		{
			title = "Importância",
			text = [=[Por muito tempo, Kelris escapou da {link:argent-dawn}Aurora Argêntea{/link}. Seus vigias em {link:darnassus}Darnassus{/link} dizem que, sempre que o mal se mostrava nestas terras, Kelris tinha participação nele, e durante anos o julgaram morto ou perdido. Não estava nem uma coisa nem outra. Descera às {link:blackfathom-deeps}Profundezas{/link} para servir aos {red:old-gods}Deuses Antigos{/red}, e pretendia devolver o mundo ao caos da era deles. Os taurens do {link:thunder-bluff}Penhasco do Trovão{/link} o chamam de criatura de puro mal.]=],
		},
		{
			title = "Feitos",
			text = [=[• Ele conduziu o {link:twilight-s-hammer}Martelo do Crepúsculo{/link} ao templo afogado de Elune.
• Ele aliou o culto aos nagas das {link:blackfathom-deeps}Profundezas Negras{/link}.
• Ele ofereceu inocentes a {link:aku-mai}Aku'mai{/link} em troca de poder.]=],
		},
	},
	chapters = {
		{
			title = "O Relatório do Batedor",
			hint = [=[Encontre o batedor perdido da Aurora Argêntea nas Profundezas.]=],
			text = [=[A {link:argent-dawn}Aurora Argêntea{/link} enviou um batedor para vigiar o templo, e semanas se passaram sem notícias. Quando enfim foi encontrado, ele jazia ferido nas cavernas, sem forças. Havia descoberto o que o culto fazia. O {link:twilight-s-hammer}Martelo do Crepúsculo{/link} e os nagas ocupavam juntos as ruínas, e seu líder, Kelris, alimentava a hidra com inocentes em troca de poder. O batedor não podia fazer mais nada. Pediu que Kelris fosse morto e sua cabeça levada para fora das {link:blackfathom-deeps}Profundezas{/link}.]=],
		},
		{
			title = "A Cabeça de Kelris",
			hint = "Ponha fim ao reinado do Senhor do Crepúsculo.",
			text = [=[Quando a cabeça de Kelris foi levada à {link:argent-dawn}Aurora Argêntea{/link} em {link:darnassus}Darnassus{/link}, o Vigia da {link:aurora-skycaller}Aurora{/link} Selgorm disse que enfim tudo fazia sentido: o homem que julgavam morto estivera por trás do mal o tempo todo. Para a {link:horde}Horda{/link}, Bashana Runetotem agradeceu à Mãe Terra e disse que sacrificar outro a um servo dos Deuses Antigos em proveito próprio era algo além das palavras. Com sua morte, muitas vidas inocentes foram poupadas.]=],
		},
	},
	mentions = {
		{ text = "A Queda do Crepúsculo" },
		{
			text = [=[Vilania nas {link:blackfathom-deeps}Profundezas Negras{/link}, a cabeça levada a {link:darnassus}Darnassus{/link}]=],
		},
		{
			text = [=[Vilania nas {link:blackfathom-deeps}Profundezas Negras{/link}, a cabeça levada ao {link:thunder-bluff}Penhasco do Trovão{/link}]=],
		},
	},
	bonds = {
		{ id = "aku-mai", name = "Aku'mai", note = "o poder a que ele serve" },
		{ id = "argent-guard-thaelrid", name = "Guarda Argênteo Thaelrid", note = "o batedor que o desmascarou" },
		{ id = "lorgus-jett", name = "Lorgus Jett", note = "um servo do mesmo culto" },
	},
})

