Translate("ptBR", "old-serra-kis", {
	title = "Velho Serra'kis",
	subtitle = "O Tubarão-raposa Inapanhável",
	found = "O Poço Esquecido, sob as Ruínas do Santuário Lunar",
	hint = [=[Mergulhe sob as ruínas para encontrar o velho tubarão-raposa do Poço Esquecido.]=],
