	aliases = { "Serra'kis" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Velho Serra'kis é um enorme tubarão-raposa que espreita numa caverna afogada sob as ruínas, onde não há ar para respirar. Diz-se que, quando o {link:twilight-s-hammer}Martelo do Crepúsculo{/link} chegou, os cultistas caçaram as criaturas das águas para comer, e a maioria delas foi devorada. Só Serra'kis não pôde ser apanhado. Os que continuaram a caçá-lo morreram na tentativa. Ele drena a vida de quem se aproxima e fica mais forte à medida que eles enfraquecem. Poucos que o procuram na água escura voltam para contar.]=],
		},
		{
			title = "Importância",
			text = [=[Serra'kis é a última grande fera das águas do velho templo, e a única presa que o culto jamais conseguiu tomar.]=],
